.gradio-authorship-display {
    display: flex;
    align-items: center;
    padding: var(--size-sm) var(--size-lg);
    border: 1px solid var(--border-color-primary);
    border-radius: var(--radius-lg);
    background: var(--background-fill-primary);
    box-shadow: var(--shadow-sm);
    gap: var(--size-md);
}

.block.gradio-authorship-display {
    margin: auto;
}

.block.gradio-authorship-display p {
    margin: 0;
    font-size: var(--text-md);
    color: var(--text-color-primary);
}

.block.gradio-authorship-display a {
    display: flex;
    align-items: center;
    gap: var(--size-sm);
    text-decoration: none;
    color: inherit;
}

.block.gradio-authorship-display a:hover {
    text-decoration: underline;
}

.block.gradio-authorship-display img {
    width: var(--size-xxl);
    height: auto;
    border-radius: 50%;
}

.block.gradio-authorship-display span {
    font-weight: 500;
}

.block.gradio-authorship-display span small {
    font-weight: 400;
    color: var(--text-color-secondary);
}

.block.card[data-testid="component-wrapper"] .gradio-authorship-display {
    display: block;
    width: 100%;
    margin: 0;
    text-align: center;
}

.block.card[data-testid="component-wrapper"] .gradio-authorship-display a {
    justify-content: center;
}

.block.card[data-testid="component-wrapper"] .gradio-authorship-display p {
    font-size: var(--text-sm);
}

